tools.example:
Application Library: Chemical_Reaction_Engineering_Module/Ideal_Tank_Reactors/chlorine_scrubber (constant-volume batch) and ibuprofen_synthesis.
model.component().create("comp1", true);
model.component("comp1").physics().create("re", "ReactionEng");
model.component("comp1").physics("re").prop("reactor").set("reactor", "batchvol");
model.component("comp1").physics("re").prop("reactor").set("Vr", "1[m^3]");
model.component("comp1").physics("re").prop("energybalance").set("energybalance", "exclude");

Application Library: Chemical_Reaction_Engineering_Module/Tutorials/cstr_startup (propylene glycol CSTR start-up with cooling) and Ideal_Tank_Reactors/tank_flow_system.
model.component("comp1").physics("re").prop("reactor").set("reactor", "cstrvol");
model.component("comp1").physics("re").prop("reactor").set("Vr", "Vr_tank");
model.component("comp1").physics("re").prop("energybalance").set("energybalance", "include");
model.component("comp1").physics("re").prop("energybalance").set("Qext", "Q_xch");

Application Library: Chemical_Reaction_Engineering_Module/Ideal_Tank_Reactors/semibatch_polymerization.
model.component("comp1").physics("re").prop("reactor").set("reactor", "semibatch");
model.component("comp1").physics("re").create("feed1", "FeedStream", -1);
model.component("comp1").physics("re").feature("feed1").set("vf", "v_feed*(t<t_feed)");

Application Library: Chemical_Reaction_Engineering_Module/Tutorials/nonisothermal_plug_flow (acetone cracking with CHEMKIN thermodynamic data).
model.component("comp1").physics("re").prop("reactor").set("reactor", "plugflow");
model.component("comp1").physics("re").prop("mixture").set("mixture", "gas");
model.component("comp1").physics("re").feature("inits1").set("F0", new String[]{"F_A0", "0", "0", "F_N2"});

Application Library: Chemical_Reaction_Engineering_Module/Tutorials/nonisothermal_plug_flow and monolith_kinetics.
model.study().create("std1");
model.study("std1").create("spf", "StationaryPlugflow");
model.study("std1").run();

Application Library: Chemical_Reaction_Engineering_Module/Tutorials/cstr_startup.
model.component("comp1").physics("re").create("rch1", "ReactionChem", -1);
model.component("comp1").physics("re").feature("rch1").set("formula", "C3H6O+H2O=>C3H8O2");
model.component("comp1").physics("re").feature("rch1").set("useArrhenius", true);
model.component("comp1").physics("re").feature("rch1").set("Af", "Af_reaction");
model.component("comp1").physics("re").feature("rch1").set("Ef", "Ea_reaction");

Application Library: Chemical_Reaction_Engineering_Module/Ideal_Tank_Reactors/chlorine_scrubber (two equilibrium reactions with one reversible reaction).
model.component("comp1").physics("re").create("rch2", "ReactionChem", -1);
model.component("comp1").physics("re").feature("rch2").set("formula", "OH-+H+=H2O");
model.component("comp1").physics("re").feature("rch2").set("Keq0", "Kequi_2");

Application Library: Chemical_Reaction_Engineering_Module/Tutorials/cstr_startup.
model.component("comp1").physics("re").feature("C3H6O").set("Cp", "cp_C3H6O");
model.component("comp1").physics("re").feature("C3H6O").set("h", "h_C3H6O");

Application Library: Chemical_Reaction_Engineering_Module/Ideal_Tank_Reactors/cubic_autocatalysis.
model.component("comp1").physics("re").create("add1", "AdditionalSourceFeature", -1);
model.component("comp1").physics("re").feature("add1").set("AddR", new String[]{"f", "0"});

Application Library: Chemical_Reaction_Engineering_Module/Tutorials/nonideal_cstr.
model.component("comp1").physics("re").create("feed1", "FeedStream", -1);
model.component("comp1").physics("re").feature("feed1").set("vf", "v0");
model.component("comp1").physics("re").feature("feed1").set("FeedSpeciesConcentration", new String[]{"c_w", "c_T0"});

Application Library: Chemical_Reaction_Engineering_Module/Tutorials/cstr_startup.
model.component("comp1").physics("re").feature("inits1").set("initialValue", new String[]{"cinit_C3H6O", "0", "0", "cinit_H2O"});
model.component("comp1").physics("re").feature("inits1").set("T0", "Tinit");

Application Library: Chemical_Reaction_Engineering_Module/Ideal_Tank_Reactors/cubic_autocatalysis (0D model extended to a 2D reaction-diffusion model).
model.component("comp1").physics("re").create("sync1", "ReactionToMph", -1);
model.component("comp1").physics("re").feature("sync1").set("massbalance", "tds");
model.component("comp1").physics("re").feature("sync1").set("study", "Stationary");

Application Library: Chemical_Reaction_Engineering_Module/Reactors_with_Mass_Transfer/TiN_cvd_reactor.
model.component("comp1").physics().create("chem", "Chemistry", "geom1");
model.component("comp1").physics("chem").prop("mixture").set("ConcentrationType", "MassFraction");
model.component("comp1").physics("chem").prop("calcTransport").set("calcTransport", "1");

Application Library: Chemical_Reaction_Engineering_Module/Reactors_with_Mass_Transfer/TiN_cvd_reactor and Mixing_and_Separation/protein_adsorption.
model.component("comp1").physics().create("sr", "SurfaceReactions", "geom1");
model.component("comp1").physics("sr").selection().set(new int[]{3});

Application Library: Chemical_Reaction_Engineering_Module/Mixing_and_Separation/barium_sulfate_precipitation (BaSO4 in a mixer).
model.component("comp1").multiphysics().create("pff1", "PrecipitationInFluidFlow", 3);
model.component("comp1").multiphysics("pff1").set("cstar_species", "c_eq");
model.component("comp1").multiphysics("pff1").set("precipitatingSpeciesMolarMass", "M_BaSO4");

Application Library: Chemical_Reaction_Engineering_Module/Reactors_with_Mass_Transfer/boat_reactor.
model.component("comp1").multiphysics().create("rfd1", "ReactingFlowDS", 2);
model.component("comp1").multiphysics("rfd1").set("Fluid_physics", "spf");
model.component("comp1").multiphysics("rfd1").set("Species_physics", "tds");

Application Library: Chemical_Reaction_Engineering_Module/Reactors_with_Mass_Transfer/TiN_cvd_reactor and CFD_Module/Nonisothermal_Flow/round_jet_burner.
model.component("comp1").multiphysics().create("nirf1", "NonIsothermalReactingFlow", 3);
model.component("comp1").multiphysics("nirf1").set("Fluid_physics", "spf");
model.component("comp1").multiphysics("nirf1").set("Species_physics", "tcs");
model.component("comp1").multiphysics("nirf1").set("Heat_physics", "ht");

Application Library: Chemical_Reaction_Engineering_Module/Mixing_and_Separation/liquid_liquid_extraction.
model.component("comp1").multiphysics("dds1").set("km_cc", "km*step1(phid)");
model.component("comp1").multiphysics("dds1").set("Kp_cc", "K_p");

Application Library: Chemical_Reaction_Engineering_Module/Electrokinetic_Effects/zone_electrophoresis and isoelectric_separation; Electrochemistry_Module/Electrochemical_Engineering/isoelectric_focusing_1d.
model.component("comp1").physics().create("el", "ElectrophoreticTransport", "geom1");
model.component("comp1").physics("el").create("wa1", "WeakAcid", 1);
